 string folder;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool good,string label){log.AppendLine((good?"PASS ":"FAIL ")+label);if(!good)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("SumoEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<SumoMatch>("TruckSumo");var m=FindAnyObjectByType<SumoMatch>();yield return null;m.setup.count=4;m.NormalizeSetup();m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);Check(m.StartMatch(),"four physical NWH AI competitors start");Time.timeScale=8;float deadline=Time.realtimeSinceStartup+600,next=0;int shoves=0,maxHeat=0;bool moved=false,replay=false,shrink=false,replayChecked=false,terminalChecked=false;while(!m.Finished&&Time.realtimeSinceStartup<deadline){foreach(var f in m.fighters){shoves=Mathf.Max(shoves,f.Shoves);moved|=f.truck.body.linearVelocity.magnitude>3;}if(m.Stage==SumoStage.Replay&&!replayChecked){int[] scores=(int[])m.rules.wins.Clone();m.ExtraAction("replayangle");m.ExtraAction("replayspeed");Check(m.replay.Angle==1&&m.replay.Speed==.5f,"actual decisive replay accepts angle and slow speed controls");m.replay.Seek(Mathf.Min(m.replay.Duration,m.replay.Cursor+1));float cursor=m.replay.Cursor;m.ExtraAction("replayrewind");Check(m.replay.Cursor<=cursor&&string.Join(",",scores)==string.Join(",",m.rules.wins),"rewind changes recorded pose time without changing scores");m.ExtraAction("replayskip");replayChecked=true;}if(m.Stage==SumoStage.Replay&&m.rules.Complete&&!terminalChecked){int winner=m.rules.Winner;m.replay.Seek(m.replay.Duration);var live=m.fighters[winner].brows[0];var ghost=Array.Find(m.replay.ghosts[winner].GetComponentsInChildren<Transform>(true),t=>t.name==live.name);Check(m.fighters[winner].Face==SumoFace.Victory&&ghost!=null&&Quaternion.Angle(live.localRotation,ghost.localRotation)<.1f,"actual final record preserves victorious eyebrow pose");terminalChecked=true;}maxHeat=Mathf.Max(maxHeat,m.rules.Heat);replay|=m.Stage==SumoStage.Replay;shrink|=m.ShrinkFrames>0;if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE heat="+m.rules.Heat+" stage="+m.Stage+" time="+m.Clock+" radius="+m.Radius+" wins="+string.Join(",",m.rules.wins)+" impacts="+m.Impacts+" errors="+errors);next=Time.realtimeSinceStartup+3;}yield return null;}Check(m.Finished&&m.rules.Winner>=0&&m.rules.wins[m.rules.Winner]==5,"complete actual first-to-five match, not injected wins");Check(moved&&shoves>0&&m.Impacts>0,"AI physically drives, uses bounded own surge and contacts opponents");Check(replay&&replayChecked&&terminalChecked,"actual recorded decisive motion and controls complete");log.AppendLine("MATCH heats="+maxHeat+" draws="+m.HeatDraws+" wins="+string.Join(",",m.rules.wins)+" winner="+m.rules.Winner+" impacts="+m.Impacts+" shrinkObserved="+shrink);m.SetupScreen();Check(m.StartMatch()&&m.rules.Heat==1&&Array.TrueForAll(m.rules.wins,w=>w==0)&&m.Radius==m.initialRadius,"rematch clears heat/score/radius/elimination/expression/replay state");Time.timeScale=1;yield return new WaitForSeconds(.2f);m.Pause();var position=m.fighters[0].truck.body.position;float clock=m.Clock;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&position==m.fighters[0].truck.body.position&&clock==m.Clock,"pause preserves truck and heat clock");m.Resume();Destroy(m.fighters[0].strain);yield return null;m.SetupScreen();Check(true,"deliberately destroyed optional tire AudioSource can be stopped safely before teardown");SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"collection return removes scene-owned replay, trucks, cameras and audio");log.AppendLine("ERRORS="+errors+". Native NWH/PhysX match simulation; no human, hardware, audio or sustained GPU acceptance claimed.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("SUMO_PROBE_COMPLETE "+log);Application.logMessageReceived-=Error;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
